-- ============================================================
-- MARKCARRO - Migração de dados históricos (planilha original)
-- Rode DEPOIS de supabase_schema.sql e supabase_fix_rls_recursao.sql.
-- Não depende de contas de login (auth.users) - importa direto pras
-- tabelas de dados. Cada bloco só roda se a tabela ainda estiver
-- vazia, então é seguro rodar esse arquivo mais de uma vez sem
-- duplicar nada.
-- ============================================================

-- ------------------------------------------------------------
-- Tabela nova: lista de e-mails (distribuição de avisos gerais -
-- não existia no schema original, veio de uma aba da planilha que
-- não estava mapeada em nenhuma tabela ainda).
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lista_emails (
  id SERIAL PRIMARY KEY,
  email TEXT NOT NULL UNIQUE
);
ALTER TABLE lista_emails ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'lista_emails' AND policyname = 'Lista de emails visivel para autenticados') THEN
    CREATE POLICY "Lista de emails visivel para autenticados" ON lista_emails
      FOR SELECT USING (auth.role() = 'authenticated');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'lista_emails' AND policyname = 'Admin gerencia lista de emails') THEN
    CREATE POLICY "Admin gerencia lista de emails" ON lista_emails
      FOR INSERT WITH CHECK (is_admin());
  END IF;
END $$;

